text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Arjun. How can I help you today?",
      "tags": ["greeting"]
    },
    {
      "speaker": "customer",
      "text": "Hi Arjun, I'm Karan Nair. I'm absolutely fed up with my internet connection. It's been dropping every ten minutes for the last two days!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am very sorry to hear that you're experiencing these drops, Mr. Nair. I know how frustrating it is when your connection is unstable.",
      "tags": ["empathy"]
    },
    {
      "speaker": "customer",
      "text": "It's making it impossible to work from home. I need this fixed right now.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I can certainly look into this for you. Before we dive into the account details, could you please provide your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, it's 41055424.",
      "tags": ["identity_verification"]
    },
    {
      "speaker": "agent",
      "text": "Thank you. I'm checking the line diagnostics now. I see some signal instability in your area at 239 MG Road.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Exactly! So what can we do about it? I can't keep doing this.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I've run a remote reset on your port, which should stabilize the signal. Could you please check if the connection is back to normal on your end?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Wait, let me see... actually, it seems to be working now. The pages are loading much faster and the signal is steady.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "That's great news. However, to ensure this doesn't happen again, I'm going to raise a network ticket to have our engineers investigate the local cabinet.",
      "tags": ["action:technician_or_ticket"]
    }
  ]
}
